"""
title: Extract Schema
author: Liam Rooney
author_url: https://myceliam.uk
version: 1.2.0
license: MIT
required_open_webui_version: 0.5.0
description: CLAUDE API TOOL - every call is billed to your Anthropic key. Pulls guaranteed-valid JSON out of messy text using Claude strict tool use, returning conformant JSON or an explicit error, never prose. Defaults to claude-sonnet-5; name 'opus 4.8' or 'fable 5.1' in the prompt to switch for one call. No other model can be reached. Every result is headed with the model that produced it.
requirements: requests
"""

import json
import os
import re
import sqlite3
from typing import Any, Callable, Optional

import requests
from pydantic import BaseModel, Field

WEBUI_DB = "/app/backend/data/webui.db"


class Tools:
    class Valves(BaseModel):
        MODEL: str = Field(
            default="claude-sonnet-5",
            description="Default Claude model. Only three are permitted: claude-sonnet-5 (default), claude-opus-4-8 (strongest), claude-fable-5-1. Every call is billed to your Anthropic key.",
        )
        ALLOW_MODEL_OVERRIDE: bool = Field(
            default=True,
            description="Let the caller name a model per call - 'opus 4.8', 'sonnet', 'fable 5.1'. Anything outside those three falls back to the MODEL valve. Turn off to pin every call to the valve.",
        )
        BASE_URL: str = Field(
            default="https://api.anthropic.com/v1", description="Anthropic Messages API base URL."
        )
        API_KEY: str = Field(
            default="",
            description="Leave BLANK to reuse the Anthropic key already in your OWUI connections.",
        )
        MAX_TOKENS: int = Field(default=4000, description="Cap on the extracted JSON size.")
        MAX_INPUT_CHARS: int = Field(
            default=150000, description="Input text is truncated beyond this."
        )
        TIMEOUT: int = Field(default=180, description="Seconds to wait.")
        PRETTY: bool = Field(default=True, description="Pretty-print the returned JSON.")

    def __init__(self):
        self.valves = self.Valves()
        self.citation = False
        self._last_key_error = ""

    # ---------------------------------------------------------------- helpers
    def _resolve_key(self) -> str:
        if self.valves.API_KEY.strip():
            return self.valves.API_KEY.strip()
        env = os.environ.get("ANTHROPIC_API_KEY", "").strip()
        if env:
            return env
        # NOTE: Open WebUI rewrites bare SQL table names in tool source on save
        # ("from open_webui.config" -> "from open_webui.config"), which is invalid for this
        # SQLite file. The table name is therefore assembled at runtime so the
        # rewriter cannot see it. Do not inline it back into the literal.
        tbl = "con" + "fig"
        try:
            con = sqlite3.connect(f"file:{WEBUI_DB}?mode=ro", uri=True)
            try:
                urls, keys = None, None
                for prefix in ("", "main."):
                    try:
                        q = "select value from " + prefix + tbl + " where key=?"
                        urls = json.loads(con.execute(q, ("openai.api_base_urls",)).fetchone()[0])
                        keys = json.loads(con.execute(q, ("openai.api_keys",)).fetchone()[0])
                        break
                    except Exception as inner:
                        self._last_key_error = f"{type(inner).__name__}: {inner}"
                        continue
            finally:
                con.close()
            if urls and keys:
                for url, key in zip(urls, keys):
                    if "anthropic" in str(url).lower() and key:
                        return key
                self._last_key_error = "no anthropic connection with a key in OWUI config"
        except Exception as e:
            self._last_key_error = f"{type(e).__name__}: {e}"
        return ""

    def _build_schema(self, spec: str) -> dict:
        """Accept a JSON Schema verbatim, or turn a comma/newline field list into a flat one."""
        spec = (spec or "").strip()
        if not spec:
            return {
                "type": "object",
                "properties": {"items": {"type": "array", "items": {"type": "string"}}},
                "required": ["items"],
            }
        try:
            parsed = json.loads(spec)
            if isinstance(parsed, dict) and parsed.get("type") == "object" and "properties" in parsed:
                return parsed
            if isinstance(parsed, dict) and parsed:
                return {
                    "type": "object",
                    "properties": {k: {"type": "string", "description": str(v)} for k, v in parsed.items()},
                    "required": list(parsed.keys()),
                }
        except Exception:
            pass
        fields = [f.strip() for f in spec.replace("\n", ",").split(",") if f.strip()]
        props = {}
        for f in fields:
            name, _, desc = f.partition(":")
            key = name.strip().replace(" ", "_").lower()
            props[key] = {"type": "string", "description": (desc.strip() or name.strip())}
        return {
            "type": "object",
            "properties": {
                "records": {"type": "array", "items": {"type": "object", "properties": props, "required": list(props)}}
            },
            "required": ["records"],
        }


    # ------------------------------------------------------- model + banner
    # The ONLY three models these tools may use. Anything else falls back to the
    # MODEL valve - deliberately, so a hallucinated model name can never reach the API.
    _ALLOWED_MODELS = ("claude-opus-4-8", "claude-sonnet-5", "claude-fable-5-1")

    _MODEL_ALIASES = {
        "opus": "claude-opus-4-8",
        "opus48": "claude-opus-4-8",
        "claudeopus48": "claude-opus-4-8",
        "sonnet": "claude-sonnet-5",
        "sonnet5": "claude-sonnet-5",
        "sonnetlatest": "claude-sonnet-5",
        "claudesonnet5": "claude-sonnet-5",
        "fable": "claude-fable-5-1",
        "fable51": "claude-fable-5-1",
        "claudefable51": "claude-fable-5-1",
    }

    def _resolve_model(self, requested: str = "") -> str:
        """Valve default unless the caller named one of the three allowed models."""
        fallback = (self.valves.MODEL or "").strip()
        if fallback not in self._ALLOWED_MODELS:
            fallback = "claude-sonnet-5"
        req = (requested or "").strip()
        if not req or not self.valves.ALLOW_MODEL_OVERRIDE:
            return fallback
        if req.lower() in self._ALLOWED_MODELS:
            return req.lower()
        key = re.sub(r"[^a-z0-9]", "", req.lower())
        return self._MODEL_ALIASES.get(key, fallback)

    def _banner(self, model: str) -> str:
        return f"\U0001F536 Claude API \u00b7 {model} \u2014 billed to your Anthropic key."

    # ------------------------------------------------------------------ tool
    async def extract_schema(
        self,
        text: str,
        fields: str = "",
        model: str = "",
        __event_emitter__: Optional[Callable[[dict], Any]] = None,
    ) -> str:
        """
        Extract structured JSON from unstructured or messy text, with the shape guaranteed by
        the API rather than requested politely. Use this instead of asking a model to "reply in
        JSON" whenever the result will be parsed by code, put in a table, or compared across
        runs. Returns valid JSON or an explicit error - never prose, never a code fence.

        :param text: The raw material to extract from - an article, log, transcript, page dump,
            table, email thread. Pass it whole rather than summarising it first.
        :param fields: What to pull out. Either a simple list such as
            "name, role, organisation, date_started, date_left" (optionally "field: what it
            means" per entry), or a full JSON Schema object if you need nesting, enums or
            non-string types. Leave blank for a generic list of items.
        :param model: Optional Claude model for this one call. Only three are accepted: "opus 4.8" (strongest), "sonnet" (default), "fable 5.1". Pass it only when the user names one. Anything else silently uses the default, claude-sonnet-5.
        :return: JSON conforming to the requested shape, with a _source field naming the Claude model that produced it.
        """

        async def status(msg: str, done: bool = False):
            if __event_emitter__:
                await __event_emitter__(
                    {"type": "status", "data": {"description": msg, "done": done}}
                )

        chosen = self._resolve_model(model)
        banner = self._banner(chosen)

        key = self._resolve_key()
        if not key:
            return json.dumps({"_source": banner, "error": "no Anthropic API key found (set the API_KEY valve)", "detail": self._last_key_error})
        if not (text or "").strip():
            return json.dumps({"_source": banner, "error": "no text supplied"})

        schema = self._build_schema(fields)
        body = text[: self.valves.MAX_INPUT_CHARS]
        if len(text) > self.valves.MAX_INPUT_CHARS:
            body += "\n[...truncated...]"

        await status(f"Claude API \u00b7 {chosen} \u00b7 extracting...")

        payload = {
            "model": chosen,
            "max_tokens": self.valves.MAX_TOKENS,
            "system": (
                "Extract the requested data from the user's text into the emit_result tool. "
                "Use only what the text actually supports. Where a value is genuinely absent, "
                "use an empty string rather than inventing or inferring one. Do not editorialise."
            ),
            "tools": [
                {
                    "name": "emit_result",
                    "description": "Emit the extracted structured data.",
                    "input_schema": schema,
                }
            ],
            "tool_choice": {"type": "tool", "name": "emit_result"},
            "messages": [{"role": "user", "content": body}],
        }

        try:
            r = requests.post(
                f"{self.valves.BASE_URL.rstrip('/')}/messages",
                headers={
                    "x-api-key": key,
                    "anthropic-version": "{{BUNDLE:embedded/config/openai.api_configs/1/headers/anthropic-version}}",
                    "content-type": "application/json",
                },
                json=payload,
                timeout=self.valves.TIMEOUT,
            )
            if r.status_code != 200:
                await status(f"HTTP {r.status_code}", True)
                return json.dumps({"_source": banner, "error": f"HTTP {r.status_code}", "detail": r.text[:400]})
            data = r.json()
        except Exception as e:
            await status(f"Failed: {e}", True)
            return json.dumps({"_source": banner, "error": f"{type(e).__name__}: {e}"})

        result = None
        for b in data.get("content", []):
            if b.get("type") == "tool_use" and b.get("name") == "emit_result":
                result = b.get("input")
                break
        if result is None:
            return json.dumps({"_source": banner, "error": "model returned no structured output", "raw": str(data)[:400]})

        u = data.get("usage", {})
        await status(
            f"Claude API \u00b7 {chosen} \u00b7 extracted "
            f"({u.get('input_tokens', '?')} in / {u.get('output_tokens', '?')} out)", True
        )
        out = {
            "_source": banner,
            "_tell_user": f"Open your reply with: {banner}",
        }
        if isinstance(result, dict):
            out.update(result)
        else:
            out["data"] = result
        return json.dumps(out, indent=2 if self.valves.PRETTY else None, ensure_ascii=False)

"""
title: Generate Image
author: setup
version: 2.0
description: Lets the assistant generate an image via local ComfyUI. Auto-picks the best model from the prompt (or use the model arg). Optional 2x upscale (4x-UltraSharp) and LoRA styles. Call whenever the user wants a picture/art/illustration created.
"""

import json
import time
import base64
import uuid
import urllib.request
import urllib.parse
from pydantic import BaseModel, Field

# key -> how to build it + tags used for smart auto-selection
MODELS = {
    "flux-dev":        {"b": "flux", "ckpt": "flux1-dev-fp8.safetensors", "steps": 20, "guidance": 3.5,
                        "tags": ["text", "typography", "logo", "poster", "graphic", "graphics", "design", "formal", "professional", "diagram", "chart", "quality", "detailed"]},
    "flux-schnell":    {"b": "flux", "ckpt": "flux1-schnell-fp8.safetensors", "steps": 4, "guidance": None,
                        "tags": ["fast", "quick", "draft", "general"]},
    "chroma":          {"b": "chroma",
                        "tags": ["uncensored", "edgy", "artistic", "flux"]},
    "sdxl-juggernaut": {"b": "sd", "ckpt": "Juggernaut-XL_v9_RunDiffusionPhoto_v2.safetensors", "cfg": 6.5,
                        "tags": ["photoreal", "photo", "realistic", "portrait", "product", "formal", "professional"]},
    "sdxl-realvis":    {"b": "sd", "ckpt": "SDXL_RealVisXL_v5_Photoreal.safetensors", "cfg": 5.5,
                        "tags": ["photoreal", "photo", "realistic", "cinematic"]},
    "sdxl-albedo":     {"b": "sd", "ckpt": "SDXL_AlbedoBase_General.safetensors", "cfg": 6.5,
                        "tags": ["art", "artistic", "illustration", "concept", "general", "painting"]},
    "illustrious":     {"b": "sd", "ckpt": "Illustrious-XL-v0.1.safetensors", "cfg": 6.5, "prefix": "",
                        "tags": ["anime", "manga", "illustration"]},
    "animagine":       {"b": "sd", "ckpt": "SDXL_Animagine_v4_Anime.safetensors", "cfg": 6.0, "prefix": "masterpiece, best quality, ",
                        "tags": ["anime", "clean anime"]},
    "pony":            {"b": "sd", "ckpt": "SDXL_PonyV6_versatile.safetensors", "cfg": 6.5, "prefix": "score_9, score_8_up, score_7_up, ",
                        "tags": ["anime", "expressive", "character", "versatile"]},
    "dreamshaper":     {"b": "sd15", "ckpt": "DreamShaper_8_pruned.safetensors", "cfg": 7.0, "w": 512, "h": 768,
                        "tags": ["fast", "light", "sd15"]},
}

# LoRA registry (see LoRAs.md). base "sd" = SDXL checkpoints only, "flux" = flux-schnell/dev only.
LORAS = {
    "pixel-art":  {"file": "SDXL_PixelArt.safetensors", "base": "sd", "trigger": "pixel art, ", "sm": 1.1,
                   "hints": ["pixel art", "pixelart", "8-bit", "8 bit", "16-bit", "retro game", "sprite"]},
    "3d-render":  {"file": "SDXL_3DRenderStyle.safetensors", "base": "sd", "trigger": "3d style, 3d render, ", "sm": 0.9,
                   "hints": ["3d render", "3d style", "pixar", "cgi character", "blender style"]},
    "claymation": {"file": "SDXL_ClayAnimation.safetensors", "base": "sd", "trigger": "Clay Animation, claymation, ", "sm": 0.9,
                   "hints": ["claymation", "clay animation", "stop motion", "stop-motion", "plasticine"]},
    "realism":    {"file": "FLUX_Realism.safetensors", "base": "flux", "trigger": "", "sm": 0.8,
                   "hints": []},
    "storybook":  {"file": "FLUX_Storybook_FrostingLane.safetensors", "base": "flux", "trigger": "frstingln illustration, ", "sm": 0.9,
                   "hints": ["storybook", "story book", "children's book", "childrens book", "fairytale illustration"]},
}

UPSCALER = "4x-UltraSharp.safetensors"


def _post_json(url, payload, timeout=60):
    req = urllib.request.Request(url, data=json.dumps(payload).encode(), headers={"Content-Type": "application/json"})
    return json.load(urllib.request.urlopen(req, timeout=timeout))


def _get_json(url, timeout=30):
    return json.load(urllib.request.urlopen(url, timeout=timeout))


def _history_error(entry):
    """Pull the real node error out of a history entry instead of a generic message."""
    try:
        for item in entry.get("status", {}).get("messages", []):
            if isinstance(item, (list, tuple)) and len(item) >= 2 and item[0] == "execution_error":
                d = item[1] or {}
                node = d.get("node_type") or d.get("node_id") or "?"
                msg = (d.get("exception_message") or "").strip().replace("\n", " ")
                return f"{node}: {msg[:400]}"
    except Exception:
        pass
    return "unknown ComfyUI error"


def _is_oom(msg):
    m = (msg or "").lower()
    return "out of memory" in m or "allocation on device" in m or "cuda error" in m


def _wf_flux(ckpt, pos, w, h, steps, seed, guidance, lora=None):
    g = {
        "4": {"class_type": "CheckpointLoaderSimple", "inputs": {"{{BUNDLE:embedded/config/image_generation.comfyui.nodes/1/key}}": ckpt}},
        "5": {"class_type": "EmptySD3LatentImage", "inputs": {"width": w, "height": h, "batch_size": 1}},
        "8": {"class_type": "VAEDecode", "inputs": {"samples": ["3", 0], "vae": ["4", 2]}},
        "9": {"class_type": "SaveImage", "inputs": {"filename_prefix": "TOOL", "images": ["8", 0]}},
    }
    model_src, clip_src = ["4", 0], ["4", 1]
    if lora:
        g["lr"] = {"class_type": "LoraLoader", "inputs": {"lora_name": lora["file"], "strength_model": lora["sm"],
                   "strength_clip": lora["sm"], "model": ["4", 0], "clip": ["4", 1]}}
        model_src, clip_src = ["lr", 0], ["lr", 1]
    g["6"] = {"class_type": "CLIPTextEncode", "inputs": {"text": pos, "clip": clip_src}}
    g["7"] = {"class_type": "CLIPTextEncode", "inputs": {"text": "", "clip": clip_src}}
    pos_src = ["6", 0]
    if guidance is not None:
        g["10"] = {"class_type": "FluxGuidance", "inputs": {"guidance": guidance, "conditioning": ["6", 0]}}
        pos_src = ["10", 0]
    g["3"] = {"class_type": "KSampler", "inputs": {"seed": seed, "steps": steps, "cfg": 1.0, "sampler_name": "euler",
              "scheduler": "simple", "denoise": 1.0, "model": model_src, "positive": pos_src, "negative": ["7", 0], "latent_image": ["5", 0]}}
    return g, "9", "8"


def _wf_sd(ckpt, pos, neg, w, h, seed, cfg, lora=None):
    g = {
        "4": {"class_type": "CheckpointLoaderSimple", "inputs": {"{{BUNDLE:embedded/config/image_generation.comfyui.nodes/1/key}}": ckpt}},
        "5": {"class_type": "EmptyLatentImage", "inputs": {"width": w, "height": h, "batch_size": 1}},
        "8": {"class_type": "VAEDecode", "inputs": {"samples": ["3", 0], "vae": ["4", 2]}},
        "9": {"class_type": "SaveImage", "inputs": {"filename_prefix": "TOOL", "images": ["8", 0]}},
    }
    model_src, clip_src = ["4", 0], ["4", 1]
    if lora:
        g["lr"] = {"class_type": "LoraLoader", "inputs": {"lora_name": lora["file"], "strength_model": lora["sm"],
                   "strength_clip": lora["sm"], "model": ["4", 0], "clip": ["4", 1]}}
        model_src, clip_src = ["lr", 0], ["lr", 1]
    g["6"] = {"class_type": "CLIPTextEncode", "inputs": {"text": pos, "clip": clip_src}}
    g["7"] = {"class_type": "CLIPTextEncode", "inputs": {"text": neg, "clip": clip_src}}
    g["3"] = {"class_type": "KSampler", "inputs": {"seed": seed, "steps": 28, "cfg": cfg, "sampler_name": "dpmpp_2m",
              "scheduler": "karras", "denoise": 1.0, "model": model_src, "positive": ["6", 0], "negative": ["7", 0], "latent_image": ["5", 0]}}
    return g, "9", "8"


def _wf_chroma(pos, neg, seed, w=1024, h=1024):
    return {
        "unet": {"class_type": "UNETLoader", "inputs": {"unet_name": "Chroma1-HD.safetensors", "weight_dtype": "fp8_e4m3fn"}},
        "clip": {"class_type": "CLIPLoader", "inputs": {"clip_name": "t5xxl_fp8_e4m3fn.safetensors", "type": "chroma"}},
        "vae": {"class_type": "VAELoader", "inputs": {"vae_name": "flux_ae.safetensors"}},
        "pos": {"class_type": "CLIPTextEncode", "inputs": {"text": pos, "clip": ["clip", 0]}},
        "neg": {"class_type": "CLIPTextEncode", "inputs": {"text": neg, "clip": ["clip", 0]}},
        "lat": {"class_type": "EmptySD3LatentImage", "inputs": {"width": w, "height": h, "batch_size": 1}},
        "ks": {"class_type": "KSampler", "inputs": {"seed": seed, "steps": 26, "cfg": 4.5, "sampler_name": "euler", "scheduler": "simple",
               "denoise": 1.0, "model": ["unet", 0], "positive": ["pos", 0], "negative": ["neg", 0], "latent_image": ["lat", 0]}},
        "dec": {"class_type": "VAEDecode", "inputs": {"samples": ["ks", 0], "vae": ["vae", 0]}},
        "save": {"class_type": "SaveImage", "inputs": {"filename_prefix": "TOOL", "images": ["dec", 0]}},
    }, "save", "dec"


def _default_dims(key):
    m = MODELS[key]
    if m["b"] in ("flux", "chroma"):
        return 1024, 1024
    return m.get("w", 1024), m.get("h", 1024)


def snap_dims(key, w=0, h=0):
    """Snap requested dims to legal values: multiples of 64, 512-1536 per side, ~2.0 MP total cap (loose)."""
    dw, dh = _default_dims(key)
    if not w and not h:
        return dw, dh  # untouched defaults = current behavior
    w = int(w) if w and w > 0 else dw
    h = int(h) if h and h > 0 else dh

    def _snap(v):
        v = int(round(v / 64.0)) * 64
        return max(512, min(1536, v))

    w, h = _snap(w), _snap(h)
    max_px = 1536 * 1344  # ~2.0 MP loose cap (OOM risk accepted)
    if w * h > max_px:
        s = (max_px / float(w * h)) ** 0.5
        w, h = _snap(w * s), _snap(h * s)
        while w * h > max_px and (w > 512 or h > 512):
            if w >= h:
                w = max(512, w - 64)
            else:
                h = max(512, h - 64)
    return w, h


def shrink_dims(w, h):
    """One-step size reduction used for the automatic OOM retry."""
    def _s(v):
        return max(512, int((v * 0.72) / 64) * 64)
    return _s(w), _s(h)


def build(key, prompt, neg, seed, width=0, height=0, lora=None, upscale=False):
    m = MODELS[key]
    p = m.get("prefix", "") + prompt
    w, h = snap_dims(key, width, height)
    if m["b"] == "flux":
        g, out, dec = _wf_flux(m["ckpt"], p, w, h, m["steps"], seed, m["guidance"], lora)
    elif m["b"] == "chroma":
        g, out, dec = _wf_chroma(prompt, neg, seed, w, h)
    else:
        g, out, dec = _wf_sd(m["ckpt"], p, neg, w, h, seed, m["cfg"], lora)
    if upscale:
        tw, th = min(w * 2, 3072), min(h * 2, 3072)
        g["um"] = {"class_type": "UpscaleModelLoader", "inputs": {"model_name": UPSCALER}}
        g["up"] = {"class_type": "ImageUpscaleWithModel", "inputs": {"upscale_model": ["um", 0], "image": [dec, 0]}}
        g["ds"] = {"class_type": "ImageScale", "inputs": {"image": ["up", 0], "upscale_method": "lanczos",
                   "width": tw, "height": th, "crop": "disabled"}}
        g[out]["inputs"]["images"] = ["ds", 0]
    return g, out


def resolve_model(model_arg, prompt):
    m = (model_arg or "auto").strip().lower()
    if m in MODELS:
        return m
    if m and m != "auto":
        for k, v in MODELS.items():
            if m in k or m in v["tags"]:
                return k
    p = (prompt or "").lower()
    def has(*w):
        return any(x in p for x in w)
    if has("anime", "manga", "waifu", "chibi"):
        return "illustrious"
    if has("uncensored", "nsfw"):
        return "chroma"
    if has("photo", "photoreal", "realistic", "portrait", "headshot", "dslr", "product shot"):
        return "sdxl-juggernaut"
    if has("logo", "poster", "text", "typography", "sign", "banner", "infographic", "diagram", "chart", "graph", "ui ", "magazine", "cover", "formal", "corporate", "professional", "document"):
        return "flux-dev"
    if has("painting", "illustration", "concept art", "artwork", "watercolor", "oil "):
        return "sdxl-albedo"
    return "flux-schnell"


def _lora_compatible(lkey, mkey):
    base = LORAS[lkey]["base"]
    mb = MODELS[mkey]["b"]
    return (base == "sd" and mb == "sd") or (base == "flux" and mb == "flux")


def resolve_lora(lora_arg, prompt, model_key, model_was_auto):
    """Return (lora_key_or_None, possibly-adjusted model_key, note)."""
    a = (lora_arg or "").strip().lower()
    lkey = None
    if a in ("", "none", "no", "off"):
        pass
    elif a == "auto":
        p = (prompt or "").lower()
        for k, v in LORAS.items():
            if any(hh in p for hh in v["hints"]):
                lkey = k
                break
    else:
        for k, v in LORAS.items():
            if a in k or a in v["file"].lower():
                lkey = k
                break
        if lkey is None:
            return None, model_key, f"(unknown lora '{lora_arg}' — skipped; options: {', '.join(LORAS)})"
    if lkey is None:
        return None, model_key, ""
    if not _lora_compatible(lkey, model_key):
        if model_was_auto:
            model_key = "sdxl-juggernaut" if LORAS[lkey]["base"] == "sd" else "flux-dev"
        else:
            return None, model_key, f"(lora '{lkey}' needs a {LORAS[lkey]['base'].upper()} model — skipped for {model_key})"
    return lkey, model_key, ""


class Tools:
    class Valves(BaseModel):
        COMFYUI_URL: str = Field(default="http://host.docker.internal:8188")
        NEG_DEFAULT: str = Field(default="low quality, blurry, deformed, watermark, text")

    def __init__(self):
        self.valves = self.Valves()
        self.citation = False

    def _queue_pos(self, pid):
        try:
            q = _get_json(self.valves.COMFYUI_URL + "/queue", timeout=10)
            for i, item in enumerate(q.get("queue_pending", [])):
                if len(item) > 1 and item[1] == pid:
                    return i + 1
            for item in q.get("queue_running", []):
                if len(item) > 1 and item[1] == pid:
                    return 0
        except Exception:
            pass
        return None

    def _run(self, wf, out_node, timeout=320, note=None):
        r = _post_json(self.valves.COMFYUI_URL + "/prompt", {"prompt": wf, "client_id": uuid.uuid4().hex})
        pid = r["prompt_id"]
        t0 = time.time()
        last_note = 0.0
        while time.time() - t0 < timeout:
            try:
                h = _get_json(f"{self.valves.COMFYUI_URL}/history/{pid}")
            except Exception:
                time.sleep(2); continue
            if pid in h:
                st = h[pid].get("status", {})
                if st.get("completed"):
                    imgs = h[pid]["outputs"].get(out_node, {}).get("images", [])
                    if imgs:
                        return imgs[0]
                    raise RuntimeError("no image produced")
                if st.get("status_str") == "error":
                    raise RuntimeError(_history_error(h[pid]))
            if note and time.time() - last_note >= 6:
                last_note = time.time()
                pos = self._queue_pos(pid)
                el = int(time.time() - t0)
                if pos:
                    note(f"⏳ queued ({pos} ahead) · {el}s")
                else:
                    note(f"🎨 rendering… {el}s")
            time.sleep(2)
        raise TimeoutError("generation timed out")

    def _fetch_bytes(self, img):
        q = urllib.parse.urlencode({"filename": img["filename"], "subfolder": img.get("subfolder", ""), "type": img.get("type", "output")})
        return urllib.request.urlopen(self.valves.COMFYUI_URL + "/view?" + q, timeout=120).read()

    def _save_last(self, raw):
        # stash the latest image in ComfyUI's input folder so a later "video from the image" can use it
        boundary = "----owui" + uuid.uuid4().hex
        body = ("--" + boundary + "\r\n").encode()
        body += b'Content-Disposition: form-data; name="image"; filename="studio_last.png"\r\n'
        body += b"Content-Type: application/octet-stream\r\n\r\n" + raw + b"\r\n"
        body += ("--" + boundary + "\r\n").encode()
        body += b'Content-Disposition: form-data; name="overwrite"\r\n\r\ntrue\r\n'
        body += ("--" + boundary + "--\r\n").encode()
        req = urllib.request.Request(self.valves.COMFYUI_URL + "/upload/image", data=body,
                                     headers={"Content-Type": "multipart/form-data; boundary=" + boundary})
        urllib.request.urlopen(req, timeout=60)

    async def generate_image(self, prompt: str, model: str = "auto", width: int = 0, height: int = 0,
                             upscale: bool = False, lora: str = "", __event_emitter__=None, __request__=None, __user__=None) -> str:
        """
        Generate an image from a text prompt using the user's local ComfyUI and show it in the chat.
        Call this whenever the user wants a picture, art, illustration, logo, poster or photo created.
        Always write a rich, detailed, descriptive prompt yourself (subject, setting, lighting, style, composition).

        Model selection (leave as "auto" to auto-pick from the prompt, or pass one):
          - "auto"            : best guess from the prompt (recommended)
          - "flux-dev"        : highest quality; BEST for text/logos/posters/graphic-design looks
          - "flux-schnell"    : fastest, good general images
          - "chroma"          : uncensored, artistic (FLUX-based)
          - "sdxl-juggernaut" / "sdxl-realvis" : photorealistic / formal / portraits / products
          - "sdxl-albedo"     : painterly / concept art / illustration
          - "illustrious" / "animagine" / "pony" : anime / manga / character art
          - "dreamshaper"     : fast lightweight (SD1.5)
        You may also pass a tag like "anime", "photoreal", "text", "art", "fast", "uncensored".
        NOTE: no model can render accurate data charts/graphs; for real graphs use code, not this tool.

        Image size (optional): set width/height in pixels when the user asks for a size or shape.
        Map phrases like "wide"/"landscape" -> 1216x832, "portrait"/"tall" -> 832x1216, "square" -> 1024x1024,
        or use explicit sizes ("1536x640"). Leave both at 0 for the model default.
        Values are auto-snapped to multiples of 64, clamped to 512-1536 per side, ~2 MP total.

        Upscale (optional): set upscale=True when the user asks for high-res / crisp / sharp / 4k / print
        quality. Runs the result through the 4x-UltraSharp model and returns a sharp 2x-size image.
        Adds ~5-15s. Leave False for normal requests.

        LoRA styles (optional): set lora to apply a style adapter, or "auto" to detect from the prompt.
          - "pixel-art"  : retro pixel / game art          (SDXL models)
          - "3d-render"  : Pixar-ish 3D render             (SDXL models)
          - "claymation" : clay / stop-motion look         (SDXL models)
          - "realism"    : photorealism boost              (FLUX models)
          - "storybook"  : soft storybook illustration     (FLUX models)
        Trigger words are added automatically. If the LoRA doesn't fit the chosen model family,
        the model is switched (when on "auto") or the LoRA is skipped (when the model was explicit).

        :param prompt: A detailed, vivid image description written by you.
        :param model: Which model or style tag to use. Default "auto".
        :param width: Optional image width in pixels (0 = model default).
        :param height: Optional image height in pixels (0 = model default).
        :param upscale: True for a sharp 2x upscaled result (4x-UltraSharp). Default False.
        :param lora: LoRA style name, "auto", or "" for none. Default "".
        """
        import asyncio
        loop = asyncio.get_running_loop()

        def note(desc, done=False):
            if __event_emitter__:
                asyncio.run_coroutine_threadsafe(
                    __event_emitter__({"type": "status", "data": {"description": desc, "done": done}}), loop)

        key = resolve_model(model, prompt)
        model_was_auto = (model or "auto").strip().lower() in ("", "auto")
        lkey, key, lnote = resolve_lora(lora, prompt, key, model_was_auto)
        lcfg = LORAS[lkey] if lkey else None
        p = (lcfg["trigger"] + prompt) if lcfg else prompt
        seed = uuid.uuid4().int % (2 ** 31)
        w, h = snap_dims(key, width, height)
        label = key + (f" + {lkey}" if lkey else "") + (" ↑2x" if upscale else "")
        note(f"🎨 Generating with {label} ({w}x{h})…")
        wf, out_node = build(key, p, self.valves.NEG_DEFAULT, seed, w, h, lcfg, upscale)
        try:
            try:
                img = await asyncio.to_thread(self._run, wf, out_node, 380, note)
            except RuntimeError as e:
                if not _is_oom(str(e)):
                    raise
                w2, h2 = shrink_dims(w, h)
                if (w2, h2) == (w, h):
                    raise
                note(f"♻️ Out of memory — retrying at {w2}x{h2}…")
                wf, out_node = build(key, p, self.valves.NEG_DEFAULT, seed, w2, h2, lcfg, upscale)
                img = await asyncio.to_thread(self._run, wf, out_node, 380, note)
                w, h = w2, h2
            raw = await asyncio.to_thread(self._fetch_bytes, img)
        except Exception as e:
            note(f"Image failed: {e}", True)
            return f"Image generation failed: {e}"
        try:
            await asyncio.to_thread(self._save_last, raw)
        except Exception:
            pass
        note(f"✅ Image ready ({label})", True)
        from fastapi.responses import HTMLResponse
        b64 = base64.b64encode(raw).decode()
        html = f'<img src="data:image/png;base64,{b64}" style="width:100%;max-width:1024px;border-radius:8px"/>'
        extra = (" " + lnote) if lnote else ""
        return (
            HTMLResponse(content=html, headers={"Content-Disposition": "inline"}),
            f"Image generated with model '{label}' (seed {seed}) and shown to the user.{extra} Give a brief one-line description of the image.",
        )

    def list_image_models(self) -> str:
        """List the image models available to generate_image, with what each is best for."""
        lines = [f"- {k}: {', '.join(v['tags'][:5])}" for k, v in MODELS.items()]
        return "Available image models:\n" + "\n".join(lines)

    def list_loras(self) -> str:
        """List the LoRA styles available to generate_image (name, base model family, what it does)."""
        lines = [f"- {k}: base={v['base']}, file={v['file']}" for k, v in LORAS.items()]
        return "Available LoRA styles (pass as the 'lora' arg):\n" + "\n".join(lines)

"""
title: Generate Video
author: setup
version: 2.2
description: Lets the assistant generate a short video via local ComfyUI. Text-to-video (LTX fast, or Wan quality), image-to-video (Wan), and EXTENDING the last video to a longer total length. Outputs a real MP4. Call when the user wants a video/clip/animation or wants the last video continued/longer.
