from pydantic import BaseModel, Field

NEG = (
    "worst quality, blurry, jittery, distorted, low quality, deformed, "
    "time-lapse, timelapse, fast motion, sped up, hyper speed, rushed frantic movement"
)

# Central generated-media folder (bind-mounted to E:\ai\generated on the host).
# Videos land here as real files, served to chats at /cache/generated/… —
# delete the file on the host and it's gone everywhere (no base64 ghost in webui.db).
MEDIA_DIR = "/app/backend/data/cache/generated"


def _central_save(data, stem):
    """Write video bytes to the central folder; returns (filename, /cache URL) or (None, None)."""
    try:
        if not os.path.isdir(MEDIA_DIR):
            return None, None
        name = f"{stem}_{time.strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex[:6]}.mp4"
        with open(os.path.join(MEDIA_DIR, name), "wb") as f:
            f.write(data)
        return name, "/cache/generated/" + name
    except Exception:
        return None, None


def _post_json(url, payload, timeout=60):
    req = urllib.request.Request(
        url,
        data=json.dumps(payload).encode(),
        headers={"Content-Type": "application/json"},
    )
    return json.load(urllib.request.urlopen(req, timeout=timeout))


def _get_json(url, timeout=30):
    return json.load(urllib.request.urlopen(url, timeout=timeout))


def _history_error(entry):
    """Pull the real node error out of a history entry instead of a generic message."""
    try:
        for item in entry.get("status", {}).get("messages", []):
            if (
                isinstance(item, (list, tuple))
                and len(item) >= 2
                and item[0] == "execution_error"
            ):
                d = item[1] or {}
                node = d.get("node_type") or d.get("node_id") or "?"
                msg = (d.get("exception_message") or "").strip().replace("\n", " ")
                return f"{node}: {msg[:400]}"
    except Exception:
        pass
    return "unknown ComfyUI error"


def _is_oom(msg):
    m = (msg or "").lower()
    return "out of memory" in m or "allocation on device" in m or "cuda error" in m


def _mp4_save(g, dec_ref, fps):
    """Append CreateVideo + SaveVideo (mp4/h264) nodes; returns the output node id."""
    g["cv"] = {"class_type": "CreateVideo", "inputs": {"images": dec_ref, "fps": fps}}
    g["mp4"] = {
        "class_type": "SaveVideo",
        "inputs": {
            "video": ["cv", 0],
            "filename_prefix": "TOOLVID",
            "format": "mp4",
            "codec": "h264",
        },
    }
    return "mp4"


