def _find_last_image(messages):
    """Return a data-URL image from the most recent message that has one, else None."""
    if not messages:
        return None
    for m in reversed(messages):
        c = m.get("content")
        if isinstance(c, list):
            for it in c:
                if it.get("type") == "image_url":
                    u = it.get("image_url", {}).get("url", "")
                    if u.startswith("data:image"):
                        return u
    return None


def resolve_video(model, has_image):
    m = (model or "auto").strip().lower()
    if "wan" in m:
        return "wan"
    if "ltx" in m:
        return "ltx"
    # auto: image present -> Wan image-to-video; else LTX fast text-to-video
    return "wan" if has_image else "ltx"


def snap_video(engine, seconds=0.0, resolution=""):
    """Map duration/resolution wishes to legal (w, h, length, fps) per engine.

    LOOSE caps (Liam's choice): Wan up to 121 frames (~5s, trained max) & 720p;
    LTX up to 385 frames (~15s @ 25fps). OOM/quality drift possible at the top end.
    """
    r = (resolution or "").strip().lower()

    def _snap32(v):
        return max(256, int(round(v / 32.0)) * 32)

    if engine == "wan":
        fps = 24.0
        if seconds and seconds > 0:
            frames = int(round(seconds * fps))
            frames = 4 * int(round((frames - 1) / 4.0)) + 1  # snap to 4n+1
            frames = max(17, min(121, frames))
        else:
            frames = 49  # current default (~2s)
        w, h = 704, 480  # current default
        if "720" in r or "hd" in r:
            w, h = 1280, 704
        if "portrait" in r or "vertical" in r or "9:16" in r:
            w, h = 704, 1280
        return _snap32(w), _snap32(h), frames, fps

    # LTX
    fps = 25.0
    if seconds and seconds > 0:
        frames = int(round(seconds * fps))
        frames = 8 * int(round((frames - 1) / 8.0)) + 1  # snap to 8n+1
        frames = max(49, min(385, frames))
    else:
        frames = 97  # current default (~3.9s)
    w, h = 768, 512  # current default
    if "720" in r or "hd" in r:
        w, h = 1280, 704
    if "portrait" in r or "vertical" in r or "9:16" in r:
        w, h = 512, 768
    return _snap32(w), _snap32(h), frames, fps


def shrink_video(w, h):
    """One-step size reduction for the automatic OOM retry."""

    def _s(v):
        return max(256, int((v * 0.72) / 32) * 32)

    return _s(w), _s(h)


class Tools:
    class Valves(BaseModel):
        COMFYUI_URL: str = Field(default="http://host.docker.internal:8188")

    def __init__(self):
        self.valves = self.Valves()
        self.citation = False

    def _upload(self, data_url):
        head, b64 = data_url.split(",", 1)
        raw = base64.b64decode(b64)
        ext = "jpg" if ("jpeg" in head or "jpg" in head) else "png"
        return self._upload_bytes(raw, f"vid_{uuid.uuid4().hex[:8]}.{ext}")

    def _upload_bytes(self, raw, fname):
        boundary = "----owui" + uuid.uuid4().hex
        body = b""
        body += ("--" + boundary + "\r\n").encode()
        body += (
            f'Content-Disposition: form-data; name="image"; filename="{fname}"\r\n'
        ).encode()
        body += b"Content-Type: application/octet-stream\r\n\r\n" + raw + b"\r\n"
        body += ("--" + boundary + "\r\n").encode()
        body += b'Content-Disposition: form-data; name="overwrite"\r\n\r\ntrue\r\n'
        body += ("--" + boundary + "--\r\n").encode()
        req = urllib.request.Request(
            self.valves.COMFYUI_URL + "/upload/image",
            data=body,
            headers={"Content-Type": "multipart/form-data; boundary=" + boundary},
        )
        return json.load(urllib.request.urlopen(req, timeout=60))["name"]

    def _queue_pos(self, pid):
        try:
            q = _get_json(self.valves.COMFYUI_URL + "/queue", timeout=10)
            for i, item in enumerate(q.get("queue_pending", [])):
                if len(item) > 1 and item[1] == pid:
                    return i + 1
            for item in q.get("queue_running", []):
                if len(item) > 1 and item[1] == pid:
                    return 0
        except Exception:
            pass
        return None

    def _run(self, wf, out_node, timeout=600, note=None):
        r = _post_json(
            self.valves.COMFYUI_URL + "/prompt",
            {"prompt": wf, "client_id": uuid.uuid4().hex},
        )
        pid = r["prompt_id"]
        t0 = time.time()
        last_note = 0.0
        while time.time() - t0 < timeout:
            try:
                h = _get_json(f"{self.valves.COMFYUI_URL}/history/{pid}")
            except Exception:
                time.sleep(3)
                continue
            if pid in h:
                st = h[pid].get("status", {})
                if st.get("completed"):
                    imgs = h[pid]["outputs"].get(out_node, {}).get("images", [])
                    if imgs:
                        return imgs[0]
                    raise RuntimeError("no video produced")
                if st.get("status_str") == "error":
                    raise RuntimeError(_history_error(h[pid]))
            if note and time.time() - last_note >= 8:
                last_note = time.time()
                pos = self._queue_pos(pid)
                el = int(time.time() - t0)
                if pos:
                    note(f"⏳ queued ({pos} ahead) · {el}s")
                else:
                    note(f"🎬 rendering… {el}s")
            time.sleep(3)
        raise TimeoutError("generation timed out")

    def _fetch_bytes(self, img):
        q = urllib.parse.urlencode(
            {
                "filename": img["filename"],
                "subfolder": img.get("subfolder", ""),
                "type": img.get("type", "output"),
            }
        )
        return urllib.request.urlopen(
            self.valves.COMFYUI_URL + "/view?" + q, timeout=180
        ).read()

    def _input_exists(self, name):
        q = urllib.parse.urlencode({"filename": name, "subfolder": "", "type": "input"})
        try:
            urllib.request.urlopen(
                self.valves.COMFYUI_URL + "/view?" + q, timeout=15
            ).read(1)
            return True
        except Exception:
            return False

    def _fetch_input_bytes(self, name):
        q = urllib.parse.urlencode({"filename": name, "subfolder": "", "type": "input"})
        try:
            return urllib.request.urlopen(
                self.valves.COMFYUI_URL + "/view?" + q, timeout=120
            ).read()
        except Exception:
            return None

    @staticmethod
    def _dur(path):
        r = subprocess.run(
            [
                "ffprobe",
                "-v",
                "error",
                "-show_entries",
                "format=duration",
                "-of",
                "csv=p=0",
                path,
            ],
            capture_output=True,
            text=True,
            timeout=60,
        )
        return float(r.stdout.strip())

    @staticmethod
    def _dims(path):
        r = subprocess.run(
            [
                "ffprobe",
                "-v",
                "error",
                "-select_streams",
                "v:0",
                "-show_entries",
                "stream=width,height",
                "-of",
                "csv=p=0",
                path,
            ],
            capture_output=True,
            text=True,
            timeout=60,
        )
        w, h = r.stdout.strip().split(",")[:2]
        return int(w), int(h)

    @staticmethod
    def _last_frame(video_path, out_png):
        for off in ("-0.25", "-1"):
            r = subprocess.run(
                [
                    "ffmpeg",
                    "-y",
                    "-sseof",
                    off,
                    "-i",
                    video_path,
                    "-frames:v",
                    "1",
                    "-q:v",
                    "2",
                    out_png,
                ],
                capture_output=True,
                text=True,
                timeout=120,
            )
            if r.returncode == 0 and os.path.exists(out_png):
                return
        raise RuntimeError("could not extract last frame: " + (r.stderr or "")[-200:])

    @staticmethod
    def _concat2(a, b, out):
        r = subprocess.run(
            [
                "ffmpeg",
                "-y",
                "-i",
                a,
                "-i",
                b,
                "-filter_complex",
                "[0:v][1:v]concat=n=2:v=1:a=0[v]",
                "-map",
                "[v]",
                "-c:v",
                "libx264",
                "-preset",
                "veryfast",
                "-crf",
                "20",
                "-pix_fmt",
                "yuv420p",
                "-r",
                "24",
                out,
            ],
            capture_output=True,
            text=True,
            timeout=600,
        )
        if r.returncode != 0:
            raise RuntimeError("ffmpeg concat: " + (r.stderr or "")[-300:])

    async def _extend_last(self, prompt, seconds, note):
        import asyncio

        base = await asyncio.to_thread(self._fetch_input_bytes, "studio_last_video.mp4")
        if base is None:
            return (
                "No previous video found to extend. Generate a video first, then ask to extend it "
                "(videos made before the extension feature can't be continued)."
            )
        tmp = tempfile.mkdtemp(prefix="ext_")
        cur = os.path.join(tmp, "cur.mp4")
        with open(cur, "wb") as f:
            f.write(base)
        try:
            dur = self._dur(cur)
            w, h = self._dims(cur)
        except Exception as e:
            return f"Could not read the last video: {e}"
        target = float(seconds) if seconds and seconds > 0 else dur + 5.0
        if target <= dur + 0.3:
            return f"The last video is already {dur:.1f}s long — you asked for {target:.1f}s total, so there's nothing to add."

        def s32(v):
            return max(256, min(1280, int(round(v / 32.0)) * 32))

        w32, h32, fps, hops = s32(w), s32(h), 24.0, 0
        while dur < target - 0.3 and hops < 3:
            remaining = min(target - dur, 5.0)
            frames = int(round(remaining * fps))
            frames = max(17, min(121, 4 * int(round((frames - 1) / 4.0)) + 1))
            hops += 1
            note(
                f"🔁 Segment {hops}: continuing from the last frame (+{frames / fps:.1f}s)…"
            )
            fpng = os.path.join(tmp, f"f{hops}.png")
            try:
                await asyncio.to_thread(self._last_frame, cur, fpng)
                with open(fpng, "rb") as f:
                    fname = await asyncio.to_thread(
                        self._upload_bytes, f.read(), f"ext_{uuid.uuid4().hex[:6]}.png"
                    )
            except Exception as e:
                return f"Could not extract/upload the continuation frame: {e}"
            seed = uuid.uuid4().int % (2**31)
            wf, out_node = wf_wan(
                prompt
                or "the scene continues, slow smooth cinematic motion, natural unhurried pace",
                w32,
                h32,
                frames,
                seed,
                fname,
                fps,
            )
            try:
                vid = await asyncio.to_thread(self._run, wf, out_node, 600, note)
                raw = await asyncio.to_thread(self._fetch_bytes, vid)
            except Exception as e:
                note(f"Extension failed: {e}", True)
                return f"Extension segment {hops} failed: {e}"
            chunk = os.path.join(tmp, f"c{hops}.mp4")
            with open(chunk, "wb") as f:
                f.write(raw)
            nxt = os.path.join(tmp, f"cur{hops}.mp4")
            try:
                await asyncio.to_thread(self._concat2, cur, chunk, nxt)
            except Exception as e:
                return f"Stitching failed: {e}"
            cur = nxt
            dur = self._dur(cur)
        with open(cur, "rb") as f:
            raw = f.read()
        try:
            await asyncio.to_thread(self._upload_bytes, raw, "studio_last_video.mp4")
        except Exception:
            pass
        note(f"✅ Extended to {dur:.1f}s ({hops} segment(s) added)", True)
        from fastapi.responses import HTMLResponse

        name, url = _central_save(raw, "extended")
        src = url or ("data:video/mp4;base64," + base64.b64encode(raw).decode())
        file_note = f" Saved as {name} in E:\\ai\\generated." if name else ""
        html = (
            '<video controls autoplay loop muted playsinline style="width:100%;max-width:768px;border-radius:8px">'
            f'<source src="{src}" type="video/mp4"></video>'
        )
        return (
            HTMLResponse(content=html, headers={"Content-Disposition": "inline"}),
            f"Video extended to ~{dur:.1f}s total ({hops} new Wan segment(s) stitched on; any original audio is not carried over).{file_note} Give a brief one-line description.",
        )

    async def generate_video(
        self,
        prompt: str,
        model: str = "auto",
        from_last_image: bool = False,
        extend_last: bool = False,
        seconds: float = 0,
        resolution: str = "",
        takes: int = 1,
        __event_emitter__=None,
        __messages__=None,
        __request__=None,
        __user__=None,
    ) -> str:
        """
        Generate a short video clip via local ComfyUI and show it in the chat as a playable MP4.
        Call this when the user wants a video, clip, animation, to animate an image, or to make
        the previous video LONGER.
        Write a rich, motion-focused prompt yourself (subject, action, camera movement, lighting, mood).
        PACING: these models exaggerate motion speed. Unless the user explicitly wants fast action,
        describe ONE simple continuous action with explicit pace words ("slow, gentle movement,
        natural speed, calm steady camera") — never a sequence of several events.

        EXTENDING a video: when the user asks to continue/extend the last video or make it last
        N seconds in total (e.g. "make it 10 seconds"), set extend_last=True and seconds to the
        desired TOTAL length. The tool takes the last frame of the previous video, generates Wan 2.2
        continuation segments (~5s each, up to 3), and stitches everything into one MP4.
        Note: each segment restarts motion from a single frame, so it plays as connected scenes
        rather than one unbroken take, and any narration/audio is dropped.

        Engines (leave "auto"):
          - "auto" : if an image is available (attached, or one just generated) -> Wan image-to-video; else LTX fast text-to-video.
          - "ltx"  : fast text-to-video (~30-50s, 768x512, ~4s clip).
          - "wan"  : higher-quality Wan 2.2; text-to-video AND image-to-video. Slower (1-3 min).

        Image-to-video: set from_last_image=True to animate the image most recently made with generate_image
        (e.g. the user says "now make a video from that image" / "animate the image"). If the user attached an
        image to the message it is used automatically. Put the desired motion/camera move in the prompt.

        Duration (optional): set seconds when the user asks, e.g. "a 5 second clip" -> seconds=5.
        Snapped to each engine's legal frame counts. Wan max ~5s; LTX max ~15s (long clips may
        strain the GPU). 0 = default (~2s Wan, ~4s LTX).

        Resolution (optional): set from phrases — "720p"/"hd" -> 1280x704, "portrait"/"vertical"
        -> tall format. Leave "" for the default (Wan 704x480, LTX 768x512).

        Takes (optional): when the user asks for several passes/takes/versions/attempts of the
        SAME idea (e.g. "do 4 passes of it"), set takes=N (max 4). The SAME prompt renders N times
        with different seeds and ALL clips are shown so the user can pick their favourite.
        Each take costs a full render (Wan ~1-3 min each), so keep takes=1 unless asked.
        Ignored when extend_last=True.

        :param prompt: A vivid description of the video / motion, written by you.
        :param model: "auto", "ltx", or "wan". Default "auto".
        :param from_last_image: True to animate the image just generated by generate_image.
        :param extend_last: True to CONTINUE the last generated video (seconds = desired TOTAL length).
        :param seconds: Desired clip length in seconds (0 = engine default). With extend_last, the TOTAL target.
        :param resolution: "" (default), "720p", "hd", or "portrait".
        :param takes: Number of independent renders of the same prompt to show (1-4, default 1).
        """
        import asyncio

        loop = asyncio.get_running_loop()

        def note(desc, done=False):
            if __event_emitter__:
                asyncio.run_coroutine_threadsafe(
                    __event_emitter__(
                        {"type": "status", "data": {"description": desc, "done": done}}
                    ),
                    loop,
                )

        if extend_last:
            return await self._extend_last(prompt, seconds, note)

        img_dataurl = _find_last_image(__messages__)
        has_image = (img_dataurl is not None) or bool(from_last_image)
        engine = resolve_video(model, has_image)
        seed = uuid.uuid4().int % (2**31)
        w, h, length, fps = snap_video(engine, seconds, resolution)
        image_name = None
        try:
            if engine == "wan":
                if img_dataurl:
                    image_name = await asyncio.to_thread(self._upload, img_dataurl)
                elif from_last_image:
                    if await asyncio.to_thread(self._input_exists, "studio_last.png"):
                        image_name = "studio_last.png"
                    else:
                        return (
                            "No recent image was found to animate. Please generate an image first "
                            "(with the Generate Image tool), then ask to make a video from it."
                        )
                wf, out_node = wf_wan(prompt, w, h, length, seed, image_name, fps)
                label = (
                    "Wan 2.2"
                    + (" (image→video)" if image_name else " (text→video)")
                    + f" {w}x{h} ~{length / fps:.1f}s"
                )
            else:
                wf, out_node = wf_ltx(prompt, w, h, length, seed, fps)
                label = f"LTX (text→video) {w}x{h} ~{length / fps:.1f}s"
        except Exception as e:
            return f"Video setup failed: {e}"
        takes = max(1, min(4, int(takes or 1)))
        results = []  # list of (seed, mp4 bytes)
        w_cur, h_cur = w, h
        for t in range(1, takes + 1):
            seed_t = seed if t == 1 else uuid.uuid4().int % (2**31)
            if engine == "wan":
                wf, out_node = wf_wan(
                    prompt, w_cur, h_cur, length, seed_t, image_name, fps
                )
            else:
                wf, out_node = wf_ltx(prompt, w_cur, h_cur, length, seed_t, fps)
            tl = label if takes == 1 else f"{label} · take {t}/{takes}"
            note(f"🎬 {tl} — rendering (can take a minute)…")
            try:
                try:
                    vid = await asyncio.to_thread(self._run, wf, out_node, 600, note)
                except RuntimeError as e:
                    if not _is_oom(str(e)):
                        raise
                    w2, h2 = shrink_video(w_cur, h_cur)
                    if (w2, h2) == (w_cur, h_cur):
                        raise
                    note(f"♻️ Out of memory — retrying at {w2}x{h2}…")
                    w_cur, h_cur = (
                        w2,
                        h2,
                    )  # keep the smaller size for the remaining takes too
                    label += f" (retried at {w2}x{h2})"
                    if engine == "wan":
                        wf, out_node = wf_wan(
                            prompt, w_cur, h_cur, length, seed_t, image_name, fps
                        )
                    else:
                        wf, out_node = wf_ltx(prompt, w_cur, h_cur, length, seed_t, fps)
                    vid = await asyncio.to_thread(self._run, wf, out_node, 600, note)
                raw = await asyncio.to_thread(self._fetch_bytes, vid)
                results.append((seed_t, raw))
            except Exception as e:
                if takes == 1:
                    note(f"Video failed: {e}", True)
                    return f"Video generation failed: {e}"
                note(f"⚠️ Take {t}/{takes} failed: {e}")
                continue
        if not results:
            note("Video failed — every take errored", True)
            return f"Video generation failed: all {takes} takes errored (last engine {label})."
        try:
            await asyncio.to_thread(
                self._upload_bytes, results[-1][1], "studio_last_video.mp4"
            )
        except Exception:
            pass
        note(
            (
                f"✅ {len(results)}/{takes} take(s) ready ({label})"
                if takes > 1
                else f"✅ Video ready ({label})"
            ),
            True,
        )
        from fastapi.responses import HTMLResponse

        parts, fnames = [], []
        for i, (sd, raw) in enumerate(results, 1):
            name, url = _central_save(raw, "toolvid")
            src = url or ("data:video/mp4;base64," + base64.b64encode(raw).decode())
            if name:
                fnames.append(name)
            cap = ""
            if len(results) > 1:
                cap = f"Take {i} · seed {sd}" + (f" · {name}" if name else "")
            elif name:
                cap = name
            if cap:
                parts.append(
                    f'<div style="font:600 13px sans-serif;margin:10px 0 4px;opacity:.85">{cap}</div>'
                )
            auto = "autoplay " if i == 1 else ""
            parts.append(
                f"<video controls {auto}loop muted playsinline "
                'style="width:100%;max-width:768px;border-radius:8px">'
                f'<source src="{src}" type="video/mp4"></video>'
            )
        html = "".join(parts)
        seeds = ", ".join(str(sd) for sd, _ in results)
        store_note = (
            f" File(s) saved in E:\\ai\\generated: {', '.join(fnames)}."
            if fnames
            else ""
        )
        if len(results) > 1:
            msg = (
                f"{len(results)} MP4 takes of the same prompt generated with {label} (seeds {seeds}), all shown "
                f"with playback controls.{store_note} The LAST take is stored for extend_last. Give a one-line "
                "description and invite the user to pick a favourite take (a take can be re-rendered by seed on request)."
            )
        else:
            msg = f"MP4 video generated with {label} (seed {seed}) and shown to the user with playback controls.{store_note} Give a brief one-line description."
        return (
            HTMLResponse(content=html, headers={"Content-Disposition": "inline"}),
            msg,
        )

"""
title: OWUI Model Feature Manager
author: Liam Rooney
author_url: https://myceliam.uk
version: 1.0.0
