required_open_webui_version: 0.11.3
description: Admin-only inspection and reversible editing of Open WebUI model capabilities, builtin tools, native tools, skills, defaults, terminal access, and function-calling mode.
"""

import copy
import hashlib
import json
import os
import re
import time
import uuid
from pathlib import Path
from typing import Any, Optional

from pydantic import BaseModel, Field

from open_webui.models.config import Config
from open_webui.models.models import ModelForm, Models
from open_webui.models.skills import Skills as SkillStore
from open_webui.models.tools import Tools as ToolStore
from open_webui.models.users import Users


BACKUP_ROOT = Path("/app/backend/data/model-feature-manager-backups")

# These are the model gates used by the installed Open WebUI 0.11.3 backend and
# represented by the current Workspace > Models editor. Missing values normally
# fall back to True, which is why the inspector reports explicit and effective
# values separately.
CAPABILITY_KEYS = (
    "file_context",
    "vision",
    "file_upload",
    "web_search",
    "image_generation",
    "code_interpreter",
    "terminal",
    "citations",
    "status_updates",
    "usage",
    "memory",
    "builtin_tools",
)

BUILTIN_TOOL_KEYS = (
    "time",
    "user_input",
    "files",
    "knowledge",
    "chats",
    "subagents",
    "memory",
    "web_search",
    "image_generation",
    "code_interpreter",
    "notes",
    "channels",
    "tasks",
    "automations",
    "calendar",
    "notifications",
)

DEFAULT_FEATURE_KEYS = ("web_search", "image_generation", "code_interpreter")

GLOBAL_CONFIG_KEYS = (
    "web.search.enable",
    "image_generation.enable",
    "images.edit.enable",
    "code_interpreter.enable",
    "notes.enable",
    "channels.enable",
    "automations.enable",
    "calendar.enable",
    "ui.enable_user_webhooks",
    "subagents.enable",
    "subagents.background_enabled",
)

FEATURE_META_KEYS = (
    "capabilities",
    "builtinTools",
    "toolIds",
    "skillIds",
    "defaultFeatureIds",
    "terminalId",
)


class Tools:
    class Valves(BaseModel):
        protected_model_ids: str = Field(
            default="q_model-feature-admin:8b",
            description=(
                "Comma-separated model IDs this tool may inspect but never edit. "
                "Keep the dedicated manager model protected so it cannot disable itself."
            ),
        )
        allow_base_model_entries: bool = Field(
            default=True,
            description=(
                "Allow changes to stored configuration overlays for provider/base models as well as derived presets."
            ),
        )
        backup_retention_per_model: int = Field(
            default=25,
            ge=1,
            le=200,
            description="Number of rollback snapshots retained per target model.",
        )

    def __init__(self):
        self.valves = self.Valves()

    # ------------------------------------------------------------------
    # authorization and model resolution
    # ------------------------------------------------------------------

    async def _require_admin(self, user_payload: Optional[dict]) -> tuple[Optional[Any], Optional[str]]:
        user_id = (user_payload or {}).get("id")
        if not user_id:
            return None, "DENIED: no authenticated Open WebUI user was supplied to the tool."
        user = await Users.get_user_by_id(user_id)
        if not user or user.role != "admin":
            return None, "DENIED: OWUI Model Feature Manager is restricted to Open WebUI administrators."
        return user, None

    async def _resolve_model(self, reference: str):
        reference = (reference or "").strip()
        if not reference:
            return None, "A model ID or exact model name is required."

        exact = await Models.get_model_by_id(reference)
        if exact:
            return exact, None

        all_models = await Models.get_all_models()
        by_name = [model for model in all_models if model.name.casefold() == reference.casefold()]
        if len(by_name) == 1:
            return by_name[0], None

        partial = [
            model
            for model in all_models
            if reference.casefold() in model.id.casefold() or reference.casefold() in model.name.casefold()
        ]
        if len(partial) == 1:
            return partial[0], None
        if partial:
            choices = [{"id": model.id, "name": model.name} for model in partial[:20]]
            return None, f"Ambiguous model reference. Use an exact ID. Matches: {json.dumps(choices)}"
        return None, f"No stored Open WebUI model configuration matches {reference!r}."

    def _protected_ids(self) -> set[str]:
        return {item.strip() for item in self.valves.protected_model_ids.split(",") if item.strip()}

    @staticmethod
    def _calling_model_id(model_payload: Optional[dict]) -> Optional[str]:
        payload = model_payload or {}
        return payload.get("id") or payload.get("model") or payload.get("model_id")

    def _mutation_denial(self, model, calling_model_id: Optional[str]) -> Optional[str]:
        if model.id in self._protected_ids():
            return f"DENIED: {model.id} is protected by this tool's Valves."
        if calling_model_id and model.id == calling_model_id:
            return "DENIED: the manager cannot edit the model currently executing the change."
        if model.base_model_id is None and not self.valves.allow_base_model_entries:
            return (
                "DENIED: this is a stored base/provider model entry and allow_base_model_entries is disabled."
            )
        return None

    # ------------------------------------------------------------------
    # inventory and effective feature reporting
    # ------------------------------------------------------------------

    @staticmethod
    def _plain_meta(model) -> dict:
        return copy.deepcopy(model.meta.model_dump())

    @staticmethod
    def _plain_params(model) -> dict:
        return copy.deepcopy(model.params.model_dump())

    @staticmethod
    def _global_gate_for_builtin(key: str, config: dict) -> Any:
        mapping = {
            "web_search": config.get("web.search.enable"),
            "image_generation": bool(
                config.get("image_generation.enable") or config.get("images.edit.enable")
            ),
            "code_interpreter": config.get("code_interpreter.enable"),
            "notes": config.get("notes.enable"),
            "channels": config.get("channels.enable"),
            "automations": config.get("automations.enable"),
            "calendar": config.get("calendar.enable"),
            "notifications": config.get("ui.enable_user_webhooks"),
            "subagents": config.get("subagents.enable"),
        }
        return mapping.get(key, "depends on chat context and user permissions")

    @staticmethod
    def _capability_dependency_for_builtin(key: str) -> Optional[str]:
        return {
            "files": "file_upload and file_context=false",
            "memory": "memory",
            "web_search": "web_search",
            "image_generation": "image_generation",
            "code_interpreter": "code_interpreter",
        }.get(key)

    async def _catalogs(self, user_id: str) -> dict:
        tools = await ToolStore.get_tools(defer_content=True)
        skills = await SkillStore.get_skills(user_id=user_id)
        return {
            # Open WebUI 0.11.3 ToolUserModel has no is_active field: presence
            # in the tool table is the availability signal. Keep the explicit
            # boolean in our output so later OWUI versions can expose it without
            # changing this tool's response shape.
            "native_tools": [
                {"id": item.id, "name": item.name, "active": bool(getattr(item, "is_active", True))}
                for item in tools
            ],
            "skills": [{"id": item.id, "name": item.name} for item in skills],
        }

    async def _feature_report(self, model, user_id: str, include_catalogs: bool) -> dict:
        meta = self._plain_meta(model)
        params = self._plain_params(model)
        caps = meta.get("capabilities") or {}
        builtins = meta.get("builtinTools") or {}
        config = await Config.get_many(*GLOBAL_CONFIG_KEYS)
        master_builtin_gate = bool(caps.get("builtin_tools", True))

        capability_report = {}
        for key in CAPABILITY_KEYS:
            capability_report[key] = {
                "configured": caps[key] if key in caps else "inherited/default",
                "model_gate": bool(caps.get(key, True)),
            }

        builtin_report = {}
        for key in BUILTIN_TOOL_KEYS:
            configured = builtins[key] if key in builtins else "inherited/default"
            category_gate = bool(builtins.get(key, True))
            dependency = self._capability_dependency_for_builtin(key)
            dependency_ok = True
            if dependency == "file_upload and file_context=false":
                dependency_ok = bool(caps.get("file_upload", True)) and not bool(
                    caps.get("file_context", True)
                )
            elif dependency:
                dependency_ok = bool(caps.get(dependency, True))
            global_gate = self._global_gate_for_builtin(key, config)
            globally_available = global_gate is not False
            builtin_report[key] = {
                "configured": configured,
                "category_gate": category_gate,
                "master_builtin_gate": master_builtin_gate,
                "capability_dependency": dependency,
                "capability_dependency_satisfied": dependency_ok,
                "global_gate": global_gate,
                "potentially_available": bool(
                    master_builtin_gate and category_gate and dependency_ok and globally_available
                ),
            }

        catalogs = await self._catalogs(user_id)
        tool_names = {item["id"]: item["name"] for item in catalogs["native_tools"]}
        skill_names = {item["id"]: item["name"] for item in catalogs["skills"]}

        report = {
            "model": {
                "id": model.id,
                "name": model.name,
                "kind": "derived workspace preset" if model.base_model_id else "base/provider configuration entry",
                "base_model_id": model.base_model_id,
                "active": model.is_active,
                "protected_from_changes": model.id in self._protected_ids(),
            },
            "function_calling": params.get("function_calling", "inherited/default"),
            "capabilities": capability_report,
            "builtin_tools": builtin_report,
            "attached_native_or_mcp_tools": [
                {
                    "id": tool_id,
                    "name": tool_names.get(tool_id),
                    "type": "mcp_server" if tool_id.startswith("server:mcp:") else "native_tool",
                    "exists_in_native_catalog": tool_id in tool_names,
                }
                for tool_id in (meta.get("toolIds") or [])
            ],
            "attached_skills": [
                {"id": skill_id, "name": skill_names.get(skill_id), "exists": skill_id in skill_names}
                for skill_id in (meta.get("skillIds") or [])
            ],
            "default_chat_features": list(meta.get("defaultFeatureIds") or []),
            "terminal_id": meta.get("terminalId"),
            "global_feature_switches": config,
            "interpretation": (
                "potentially_available is the model/config gate, not a guarantee: per-user permissions, "
                "chat feature switches, attachment state, and UI/native function-calling context can still block a feature."
            ),
        }
        if include_catalogs:
            report["available_catalogs"] = {
                **catalogs,
                "capability_keys": list(CAPABILITY_KEYS),
                "builtin_tool_keys": list(BUILTIN_TOOL_KEYS),
                "default_feature_keys": list(DEFAULT_FEATURE_KEYS),
            }
        return report

    # ------------------------------------------------------------------
    # change validation, preview and application
    # ------------------------------------------------------------------

    @staticmethod
    def _load_changes(changes_json: str) -> tuple[Optional[dict], Optional[str]]:
        try:
            changes = json.loads(changes_json)
        except Exception as exc:
            return None, f"Invalid changes_json: {type(exc).__name__}: {exc}"
        if not isinstance(changes, dict) or not changes:
            return None, "changes_json must be a non-empty JSON object."
        return changes, None

    @staticmethod
    def _validate_toggle_map(value: Any, allowed: tuple[str, ...], field: str) -> tuple[dict, list[str]]:
        errors = []
        if value is None:
            return {}, errors
        if not isinstance(value, dict):
            return {}, [f"{field} must be an object mapping names to true, false, or null."]
        result = {}
        for key, enabled in value.items():
            if key not in allowed:
                errors.append(f"Unknown {field} key {key!r}.")
            elif enabled is not None and not isinstance(enabled, bool):
                errors.append(f"{field}.{key} must be true, false, or null.")
            else:
                result[key] = enabled
        return result, errors

    async def _normalize_changes(self, changes: dict, user_id: str) -> tuple[Optional[dict], list[str], list[str]]:
        allowed_top = {
            "is_active",
            "function_calling",
            "capabilities",
            "builtin_tools",
            "native_tools",
            "skills",
            "default_features",
            "terminal_id",
        }
        errors = [f"Unknown top-level field {key!r}." for key in changes if key not in allowed_top]
        warnings = []
        normalized = {}

        if "is_active" in changes:
            if not isinstance(changes["is_active"], bool):
                errors.append("is_active must be true or false.")
            else:
                normalized["is_active"] = changes["is_active"]

        if "function_calling" in changes:
            value = changes["function_calling"]
            if value not in (None, "native", "legacy"):
                errors.append("function_calling must be 'native', 'legacy', or null (inherit/default).")
            else:
                normalized["function_calling"] = value

        capabilities, errs = self._validate_toggle_map(
            changes.get("capabilities"), CAPABILITY_KEYS, "capabilities"
        )
        errors.extend(errs)
        if capabilities:
            normalized["capabilities"] = capabilities

        builtins, errs = self._validate_toggle_map(
            changes.get("builtin_tools"), BUILTIN_TOOL_KEYS, "builtin_tools"
        )
        errors.extend(errs)
        if builtins:
            normalized["builtin_tools"] = builtins

        defaults, errs = self._validate_toggle_map(
            changes.get("default_features"), DEFAULT_FEATURE_KEYS, "default_features"
        )
        errors.extend(errs)
        if defaults:
            normalized["default_features"] = defaults

        catalogs = await self._catalogs(user_id)
        available_tools = {item["id"] for item in catalogs["native_tools"] if item["active"]}
        available_skills = {item["id"] for item in catalogs["skills"]}

        native_tools = changes.get("native_tools")
        if native_tools is not None:
            if not isinstance(native_tools, dict):
                errors.append("native_tools must map tool IDs to true or false.")
            else:
                clean = {}
                for tool_id, enabled in native_tools.items():
                    if not isinstance(enabled, bool):
                        errors.append(f"native_tools.{tool_id} must be true or false.")
                    elif enabled and tool_id not in available_tools:
                        errors.append(
                            f"Cannot attach unknown/inactive native tool {tool_id!r}. MCP server IDs may be removed "
                            "if already attached, but this tool does not invent or attach unverified MCP server IDs."
                        )
                    else:
                        clean[tool_id] = enabled
                if clean:
                    normalized["native_tools"] = clean

        skills = changes.get("skills")
        if skills is not None:
            if not isinstance(skills, dict):
                errors.append("skills must map skill IDs to true or false.")
            else:
                clean = {}
                for skill_id, enabled in skills.items():
                    if not isinstance(enabled, bool):
                        errors.append(f"skills.{skill_id} must be true or false.")
                    elif enabled and skill_id not in available_skills:
                        errors.append(f"Cannot attach unknown skill {skill_id!r}.")
                    else:
                        clean[skill_id] = enabled
                if clean:
                    normalized["skills"] = clean

        if "terminal_id" in changes:
            value = changes["terminal_id"]
            if value is not None and (not isinstance(value, str) or not value.strip()):
                errors.append("terminal_id must be a non-empty string or null.")
            else:
                normalized["terminal_id"] = value.strip() if isinstance(value, str) else None

        if normalized.get("builtin_tools", {}).get("subagents") is True:
            global_config = await Config.get_many("subagents.enable")
            if not global_config.get("subagents.enable"):
                warnings.append(
                    "Sub-agents would be enabled for this model but remain unavailable while the global subagents.enable switch is false."
                )
        if normalized.get("builtin_tools", {}).get("notifications") is True:
            global_config = await Config.get_many("ui.enable_user_webhooks")
            if not global_config.get("ui.enable_user_webhooks"):
                warnings.append(
                    "Notifications would be enabled for this model but remain unavailable while ui.enable_user_webhooks is false."
                )

        if not normalized and not errors:
            errors.append("No supported changes were supplied.")
        return (normalized if not errors else None), errors, warnings

    @staticmethod
    def _feature_state(model) -> dict:
        meta = model.meta.model_dump()
        params = model.params.model_dump()
        return {
            "is_active": model.is_active,
            "function_calling": {
                "present": "function_calling" in params,
                "value": params.get("function_calling"),
            },
            "meta": {
                key: {"present": key in meta, "value": copy.deepcopy(meta.get(key))}
                for key in FEATURE_META_KEYS
            },
        }

    @staticmethod
    def _token(model_id: str, before_state: dict, normalized_changes: dict) -> str:
        payload = json.dumps(
            {"model_id": model_id, "before": before_state, "changes": normalized_changes},
            sort_keys=True,
            separators=(",", ":"),
        )
        return hashlib.sha256(payload.encode("utf-8")).hexdigest()[:24]

    @staticmethod
    def _set_or_remove(mapping: dict, key: str, value: Any) -> None:
        if value is None:
            mapping.pop(key, None)
        else:
            mapping[key] = value

    def _project_changes(self, model, changes: dict) -> tuple[dict, dict, bool]:
        meta = self._plain_meta(model)
        params = self._plain_params(model)
        active = model.is_active

        if "is_active" in changes:
            active = changes["is_active"]
        if "function_calling" in changes:
            self._set_or_remove(params, "function_calling", changes["function_calling"])

        caps = copy.deepcopy(meta.get("capabilities") or {})
        for key, value in changes.get("capabilities", {}).items():
            self._set_or_remove(caps, key, value)
        if "capabilities" in changes:
            meta["capabilities"] = caps

        builtins = copy.deepcopy(meta.get("builtinTools") or {})
        for key, value in changes.get("builtin_tools", {}).items():
            self._set_or_remove(builtins, key, value)
        if "builtin_tools" in changes:
            meta["builtinTools"] = builtins

        tool_ids = list(meta.get("toolIds") or [])
        for tool_id, enabled in changes.get("native_tools", {}).items():
            if enabled and tool_id not in tool_ids:
                tool_ids.append(tool_id)
            elif not enabled and tool_id in tool_ids:
                tool_ids.remove(tool_id)
        if "native_tools" in changes:
            meta["toolIds"] = tool_ids

        skill_ids = list(meta.get("skillIds") or [])
        for skill_id, enabled in changes.get("skills", {}).items():
            if enabled and skill_id not in skill_ids:
                skill_ids.append(skill_id)
            elif not enabled and skill_id in skill_ids:
                skill_ids.remove(skill_id)
        if "skills" in changes:
            meta["skillIds"] = skill_ids

        defaults = list(meta.get("defaultFeatureIds") or [])
        for feature_id, enabled in changes.get("default_features", {}).items():
            if enabled and feature_id not in defaults:
                defaults.append(feature_id)
            elif not enabled and feature_id in defaults:
                defaults.remove(feature_id)
        if "default_features" in changes:
            meta["defaultFeatureIds"] = defaults

        if "terminal_id" in changes:
            self._set_or_remove(meta, "terminalId", changes["terminal_id"])

        return meta, params, active

    @staticmethod
    def _state_diff(before: Any, after: Any, path: str = "") -> list[dict]:
        """Return leaf-level changes so previews stay readable and auditable."""
        if isinstance(before, dict) and isinstance(after, dict):
            changes = []
            for key in sorted(set(before) | set(after)):
                child = f"{path}.{key}" if path else key
                changes.extend(
                    Tools._state_diff(before.get(key), after.get(key), child)
                )
            return changes
        if before != after:
            return [{"path": path or "$", "before": before, "after": after}]
        return []

    def _write_backup(self, model, user_id: str, before_state: dict, changes: dict) -> str:
        BACKUP_ROOT.mkdir(mode=0o700, parents=True, exist_ok=True)
        backup_id = f"{int(time.time())}-{uuid.uuid4().hex[:10]}"
        target_hash = hashlib.sha256(model.id.encode("utf-8")).hexdigest()[:16]
        payload = {
            "version": 1,
            "backup_id": backup_id,
            "created_at": int(time.time()),
            "actor_user_id": user_id,
            "target_model_id": model.id,
            "target_model_name": model.name,
            "before": before_state,
            "applied_changes": changes,
        }
        final_path = BACKUP_ROOT / f"{target_hash}-{backup_id}.json"
        temp_path = BACKUP_ROOT / f".{target_hash}-{backup_id}.tmp"
        temp_path.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
        os.chmod(temp_path, 0o600)
        os.replace(temp_path, final_path)
        self._prune_backups(model.id)
        return backup_id

    def _backup_records(self, model_id: str) -> list[tuple[Path, dict]]:
        if not BACKUP_ROOT.exists():
            return []
        target_hash = hashlib.sha256(model_id.encode("utf-8")).hexdigest()[:16]
        records = []
        for path in BACKUP_ROOT.glob(f"{target_hash}-*.json"):
            try:
                data = json.loads(path.read_text(encoding="utf-8"))
                if data.get("target_model_id") == model_id:
                    records.append((path, data))
            except Exception:
                continue
        return sorted(records, key=lambda item: (item[1].get("created_at", 0), item[0].name), reverse=True)

    def _prune_backups(self, model_id: str) -> None:
        for path, _ in self._backup_records(model_id)[self.valves.backup_retention_per_model :]:
            path.unlink(missing_ok=True)

    # ------------------------------------------------------------------
    # public tools
    # ------------------------------------------------------------------

    async def list_configured_models(self, __user__: dict = {}) -> str:
        """List stored Open WebUI model configurations that can be inspected or managed.

        This is read-only. Use it when the user's model name is not an exact model ID.
        """
        user, error = await self._require_admin(__user__)
        if error:
            return error
        models = await Models.get_all_models()
        result = [
            {
                "id": model.id,
                "name": model.name,
                "kind": "preset" if model.base_model_id else "base/provider entry",
                "base_model_id": model.base_model_id,
                "active": model.is_active,
                "protected": model.id in self._protected_ids(),
            }
            for model in sorted(models, key=lambda item: item.name.casefold())
        ]
        return json.dumps(result, indent=2)

    async def inspect_model_features(
        self,
        model_id_or_name: str,
        include_available_catalogs: bool = True,
        __user__: dict = {},
    ) -> str:
        """Show a model's full feature configuration before proposing changes.

        Reports capability gates such as vision and terminal, every builtin-tool
        category including notifications and sub-agents, attached native/MCP tools,
        skills, default chat features, function-calling mode, and relevant global
        switches. Missing settings are shown as inherited/default rather than hidden.

        :param model_id_or_name: Exact model ID, exact display name, or an unambiguous partial match.
        :param include_available_catalogs: Include all native tools, skills, and valid setting names that could be used in a change request.
        """
        user, error = await self._require_admin(__user__)
        if error:
            return error
        model, error = await self._resolve_model(model_id_or_name)
        if error:
            return error
        report = await self._feature_report(model, user.id, include_available_catalogs)
        return json.dumps(report, indent=2, sort_keys=True)

    async def change_model_features(
        self,
        model_id_or_name: str,
        changes_json: str,
        preview_token: str = "",
        __user__: dict = {},
        __model__: dict = {},
    ) -> str:
        """Preview or apply a reversible change to another model's features.

        ALWAYS call inspect_model_features first. On the first call, leave
        preview_token empty; this returns an exact diff and a preview token without
        changing anything. Show that preview to the user. After the user approves,
        repeat the identical call with the returned token to apply it. Every applied
        change creates a persistent rollback snapshot.

        changes_json supports:
        {
          "is_active": true,
          "function_calling": "native" | "legacy" | null,
          "capabilities": {"vision": false, "terminal": false},
          "builtin_tools": {"notifications": true, "subagents": false},
          "native_tools": {"run_python": false, "nvd_recent_cves": true},
          "skills": {"cve": true},
          "default_features": {"web_search": false},
          "terminal_id": "OpenTerminal" | null
        }
        For capabilities and builtin_tools, null removes the explicit override and
        returns that setting to Open WebUI's inherited/default behavior.

        :param model_id_or_name: Target model ID or exact/unambiguous name. The executing manager model cannot target itself.
        :param changes_json: JSON object containing only the requested feature changes.
        :param preview_token: {{BUNDLE:embedded/tool/model_feature_manager/specs/0/parameters/properties/preview_token/description}}
        """
        user, error = await self._require_admin(__user__)
        if error:
            return error
        model, error = await self._resolve_model(model_id_or_name)
        if error:
            return error
        denial = self._mutation_denial(model, self._calling_model_id(__model__))
        if denial:
            return denial

        raw_changes, error = self._load_changes(changes_json)
        if error:
            return error
        changes, errors, warnings = await self._normalize_changes(raw_changes, user.id)
        if errors:
            return json.dumps({"status": "INVALID", "errors": errors, "warnings": warnings}, indent=2)

        before_state = self._feature_state(model)
        token = self._token(model.id, before_state, changes)
        projected_meta, projected_params, projected_active = self._project_changes(model, changes)
        projected = {
            "is_active": projected_active,
            "function_calling": {
                "present": "function_calling" in projected_params,
                "value": projected_params.get("function_calling"),
            },
            "meta": {
                key: {"present": key in projected_meta, "value": copy.deepcopy(projected_meta.get(key))}
                for key in FEATURE_META_KEYS
            },
        }
        diff = self._state_diff(before_state, projected)
        if not diff:
            return json.dumps(
                {"status": "NO_CHANGE", "model_id": model.id, "warnings": warnings}, indent=2
            )

        if not preview_token:
            return json.dumps(
                {
                    "status": "PREVIEW_ONLY",
                    "model_id": model.id,
                    "model_name": model.name,
                    "diff": diff,
                    "warnings": warnings,
                    "preview_token": token,
                    "next_step": (
                        "Present this exact diff to the user. Apply only after approval by repeating the identical "
                        "change_model_features call with this preview_token."
                    ),
                },
                indent=2,
                sort_keys=True,
            )

        if preview_token != token:
            return json.dumps(
                {
                    "status": "STALE_OR_INVALID_PREVIEW",
                    "message": "The target configuration or requested change differs from the preview. Preview again.",
                },
                indent=2,
            )

        backup_id = self._write_backup(model, user.id, before_state, changes)
        updated_form = ModelForm(
            id=model.id,
            base_model_id=model.base_model_id,
            name=model.name,
            meta=projected_meta,
            params=projected_params,
            access_grants=[grant.model_dump() for grant in model.access_grants],
            is_active=projected_active,
        )
        updated = await Models.update_model_by_id(model.id, updated_form)
        if not updated:
            return json.dumps(
                {
                    "status": "FAILED",
                    "message": "Open WebUI did not update the model. The pre-change snapshot was retained.",
                    "backup_id": backup_id,
                },
                indent=2,
            )

        verified_state = self._feature_state(updated)
        if verified_state != projected:
            return json.dumps(
                {
                    "status": "VERIFY_FAILED",
                    "message": "The saved feature state did not match the requested projection. Use restore_model_features.",
                    "backup_id": backup_id,
                    "expected": projected,
                    "actual": verified_state,
                },
                indent=2,
                sort_keys=True,
            )

        return json.dumps(
            {
                "status": "APPLIED_AND_VERIFIED",
                "model_id": model.id,
                "model_name": model.name,
                "diff": diff,
                "warnings": warnings,
                "backup_id": backup_id,
                "rollback": (
                    f"Call restore_model_features for {model.id!r} with backup_id {backup_id!r}; "
                    "first without a preview token, then repeat with the returned token after approval."
                ),
            },
            indent=2,
            sort_keys=True,
        )

    async def list_model_feature_backups(
        self, model_id_or_name: str, __user__: dict = {}
    ) -> str:
        """List rollback snapshots created by this tool for one model. This is read-only.

        :param model_id_or_name: Target model ID or exact/unambiguous display name.
        """
        user, error = await self._require_admin(__user__)
        if error:
            return error
        model, error = await self._resolve_model(model_id_or_name)
        if error:
            return error
        records = [
            {
                "backup_id": data.get("backup_id"),
                "created_at": data.get("created_at"),
                "applied_changes": data.get("applied_changes"),
            }
            for _, data in self._backup_records(model.id)
        ]
        return json.dumps({"model_id": model.id, "backups": records}, indent=2, sort_keys=True)

    async def restore_model_features(
        self,
        model_id_or_name: str,
        backup_id: str,
        preview_token: str = "",
        __user__: dict = {},
        __model__: dict = {},
    ) -> str:
        """Preview or restore a model feature snapshot created by this tool.

        Leave preview_token empty to receive the restore diff and token. Show the
        preview to the user. After approval, repeat the identical call with the token.
        Restoring also creates a new snapshot of the current state, so a restore can
        itself be reversed.

        :param model_id_or_name: Target model ID or exact/unambiguous display name.
        :param backup_id: Backup ID returned by an applied change or list_model_feature_backups.
        :param preview_token: {{BUNDLE:embedded/tool/model_feature_manager/specs/4/parameters/properties/preview_token/description}}
        """
        user, error = await self._require_admin(__user__)
        if error:
            return error
        model, error = await self._resolve_model(model_id_or_name)
        if error:
            return error
        denial = self._mutation_denial(model, self._calling_model_id(__model__))
        if denial:
            return denial

        record = next(
            (data for _, data in self._backup_records(model.id) if data.get("backup_id") == backup_id),
            None,
        )
        if not record:
            return f"No backup {backup_id!r} exists for model {model.id!r}."

        current_state = self._feature_state(model)
        restore_state = record.get("before")
        if not isinstance(restore_state, dict):
            return "Backup is invalid: missing feature state."
        restore_request = {"restore_backup_id": backup_id}
        token = self._token(model.id, current_state, restore_request)
        diff = self._state_diff(current_state, restore_state)
        if not diff:
            return json.dumps({"status": "NO_CHANGE", "model_id": model.id}, indent=2)

        if not preview_token:
            return json.dumps(
                {
                    "status": "RESTORE_PREVIEW_ONLY",
                    "model_id": model.id,
                    "backup_id": backup_id,
                    "diff": diff,
                    "preview_token": token,
                    "next_step": "Present this diff to the user and repeat with the token only after approval.",
                },
                indent=2,
                sort_keys=True,
            )
        if preview_token != token:
            return json.dumps(
                {
                    "status": "STALE_OR_INVALID_PREVIEW",
                    "message": "The current configuration changed after the restore preview. Preview again.",
                },
                indent=2,
            )

        meta = self._plain_meta(model)
        params = self._plain_params(model)
        for key, entry in restore_state.get("meta", {}).items():
            if key not in FEATURE_META_KEYS or not isinstance(entry, dict):
                continue
            if entry.get("present"):
                meta[key] = copy.deepcopy(entry.get("value"))
            else:
                meta.pop(key, None)
        fc = restore_state.get("function_calling", {})
        if fc.get("present"):
            params["function_calling"] = fc.get("value")
        else:
            params.pop("function_calling", None)
        active = bool(restore_state.get("is_active", model.is_active))

        safety_backup_id = self._write_backup(model, user.id, current_state, restore_request)
        updated = await Models.update_model_by_id(
            model.id,
            ModelForm(
                id=model.id,
                base_model_id=model.base_model_id,
                name=model.name,
                meta=meta,
                params=params,
                access_grants=[grant.model_dump() for grant in model.access_grants],
                is_active=active,
            ),
        )
        if not updated or self._feature_state(updated) != restore_state:
            return json.dumps(
                {
                    "status": "RESTORE_VERIFY_FAILED",
                    "safety_backup_id": safety_backup_id,
                },
                indent=2,
            )
        return json.dumps(
            {
                "status": "RESTORED_AND_VERIFIED",
                "model_id": model.id,
                "restored_backup_id": backup_id,
                "safety_backup_id": safety_backup_id,
                "diff": diff,
            },
            indent=2,
            sort_keys=True,
        )

