from pydantic import BaseModel, Field


API_BASE_URL = "https://www.googleapis.com/youtube/v3"
CHANNEL_ID_RE = re.compile(r"^UC[A-Za-z0-9_-]{22}$")
SUPPORTED_YOUTUBE_HOSTS = {
    "youtube.com",
    "www.youtube.com",
    "m.youtube.com",
    "music.youtube.com",
}
MAX_VIDEO_COUNT = 500


class YouTubeToolError(RuntimeError):
    """Actionable error that is safe to return to the chat."""


def _single_line(value: Any) -> str:
    """Collapse API text to one display line without adding metadata."""

    return " ".join(str(value or "").split())


def parse_channel_reference(raw_channel: str) -> Tuple[str, str]:
    """Return the official channels.list filter name and value."""

    value = (raw_channel or "").strip()
    if not value:
        raise ValueError("Provide a YouTube channel ID, @handle, or channel URL.")

    if CHANNEL_ID_RE.fullmatch(value):
        return "id", value

    if value.startswith("@"):
        handle = value[1:].strip()
        if not handle or any(ch.isspace() for ch in handle) or any(ch in "/?#" for ch in handle):
            raise ValueError("The @handle is invalid. Use the exact handle shown on YouTube.")
        return "forHandle", handle

    candidate = value
    lowered = candidate.lower()
    if "://" not in candidate and any(
        lowered.startswith(prefix)
        for prefix in (
            "youtube.com/",
            "www.youtube.com/",
            "m.youtube.com/",
            "music.youtube.com/",
        )
    ):
        candidate = "https://" + candidate

    parsed = urlparse(candidate)
    host = (parsed.hostname or "").lower().rstrip(".")
    if not parsed.scheme or not host:
        raise ValueError("Provide a YouTube channel ID, @handle, or full channel URL.")
    if parsed.scheme.lower() not in {"http", "https"} or host not in SUPPORTED_YOUTUBE_HOSTS:
        raise ValueError("The URL must be a supported youtube.com channel URL.")
    try:
        port = parsed.port
    except ValueError as exc:
        raise ValueError("The YouTube channel URL contains an invalid port.") from exc
    if parsed.username or parsed.password or port:
        raise ValueError("YouTube channel URLs must not contain credentials or a custom port.")

    parts = [unquote(part).strip() for part in parsed.path.split("/") if part.strip()]
    if not parts:
        raise ValueError("The YouTube URL does not identify a channel.")

    first = parts[0]
    if first.startswith("@"):
        handle = first[1:].strip()
        if not handle or any(ch.isspace() for ch in handle):
            raise ValueError("The channel URL contains an invalid @handle.")
        return "forHandle", handle

    if first.lower() == "channel" and len(parts) >= 2:
        channel_id = parts[1]
        if not CHANNEL_ID_RE.fullmatch(channel_id):
            raise ValueError("The /channel/ URL does not contain a valid YouTube channel ID.")
        return "id", channel_id

    if first.lower() == "user" and len(parts) >= 2:
        username = parts[1]
        if not username or any(ch.isspace() for ch in username):
            raise ValueError("The legacy /user/ URL contains an invalid username.")
        return "forUsername", username

    if first.lower() == "c" or len(parts) == 1:
        raise ValueError(
            "Legacy YouTube vanity URLs such as /c/name or /name cannot be resolved "
            "reliably. Use the channel's @handle or UC... channel ID instead."
        )

    raise ValueError(
        "Unsupported YouTube URL. Use /@handle, /channel/UC..., an @handle, or a UC... channel ID."
    )


def _google_error_reason(response: requests.Response) -> Optional[str]:
    """Extract a reason code without returning the request URL or API key."""

    try:
        payload = response.json()
    except ValueError:
        return None
    error = payload.get("error") if isinstance(payload, dict) else None
    errors = error.get("errors") if isinstance(error, dict) else None
    if isinstance(errors, list) and errors and isinstance(errors[0], dict):
        return _single_line(errors[0].get("reason")) or None
    return None


def _api_error(response: requests.Response) -> YouTubeToolError:
    """Map official API failures to concise messages without leaking the key."""

    reason = _google_error_reason(response)
    status = response.status_code
    if reason in {"quotaExceeded", "dailyLimitExceeded"}:
        return YouTubeToolError(
            "YouTube Data API quota is exhausted. Wait for the quota reset or use a project with available quota."
        )
    if reason in {"rateLimitExceeded", "userRateLimitExceeded"} or status == 429:
        return YouTubeToolError("YouTube Data API rate limit reached. Wait briefly and try again.")
    if reason in {"keyInvalid", "badRequest"} or status == 401:
        return YouTubeToolError(
            "YouTube Data API key was rejected. Check the masked Tool Valve and confirm YouTube Data API v3 is enabled."
        )
    if reason in {"accessNotConfigured", "forbidden", "ipRefererBlocked"}:
        return YouTubeToolError(
            "YouTube Data API access is not enabled for this key, or its restrictions block Open WebUI. "
            "Enable YouTube Data API v3 and allow server-side requests."
        )
    if status == 404:
        return YouTubeToolError("YouTube channel or uploads playlist was not found.")
    return YouTubeToolError(f"YouTube Data API request failed with HTTP {status}.")


class Tools:
    class Valves(BaseModel):
        youtube_data_api_key: str = Field(
            default="",
            description=(
                "YouTube Data API v3 key. Paste it here; this field is masked. Restrict the Google key "
                "to YouTube Data API v3. It is never accepted as a tool-call argument or included in output."
            ),
            json_schema_extra={"input": {"type": "password"}},
        )
        request_timeout: int = Field(
            default=30,
            ge=5,
            le=120,
            description="Per-request timeout in seconds (5-120).",
        )
        max_video_count: int = Field(
            default=MAX_VIDEO_COUNT,
            ge=1,
            le=MAX_VIDEO_COUNT,
            description="Safety cap for one response. Maximum 500 videos.",
        )

    def __init__(self):
        self.valves = self.Valves()
        self.citation = False

    def _get_json(
        self,
        session: requests.Session,
        path: str,
        params: Dict[str, Any],
    ) -> Dict[str, Any]:
        key = (self.valves.youtube_data_api_key or "").strip()
        if not key:
            raise YouTubeToolError(
                "YouTube Channel Videos is installed but not configured. Open Workspace > Tools > "
                "YouTube Channel Videos > Valves, then paste the key into the masked "
                "youtube_data_api_key field."
            )

        try:
            response = session.get(
                f"{API_BASE_URL}/{path}",
                params={**params, "key": key},
                headers={
                    "Accept": "application/json",
                    "User-Agent": "open-webui-youtube-channel-videos/1.0",
                },
                timeout=self.valves.request_timeout,
                allow_redirects=False,
            )
        except requests.Timeout as exc:
            raise YouTubeToolError("YouTube Data API request timed out. Try again.") from exc
        except requests.RequestException as exc:
            raise YouTubeToolError(
                "Could not reach the YouTube Data API. Check Open WebUI network access."
            ) from exc

        if response.status_code >= 400:
            raise _api_error(response)
        try:
            payload = response.json()
        except ValueError as exc:
            raise YouTubeToolError("YouTube Data API returned invalid JSON.") from exc
        if not isinstance(payload, dict):
            raise YouTubeToolError("YouTube Data API returned an unexpected response.")
        return payload

    def _resolve_channel(
        self,
        session: requests.Session,
        filter_name: str,
        filter_value: str,
    ) -> Tuple[str, str, str]:
        payload = self._get_json(
            session,
            "channels",
            {
                "part": "snippet,contentDetails",
                filter_name: filter_value,
                "maxResults": 1,
                "fields": "items(id,snippet/title,contentDetails/relatedPlaylists/uploads)",
            },
        )
        items = payload.get("items") or []
        if not items:
            raise YouTubeToolError(
                "YouTube channel not found. Check the @handle or UC... channel ID; "
                "legacy /c/ vanity URLs are unsupported."
            )

        channel = items[0]
        channel_id = _single_line(channel.get("id"))
        channel_title = _single_line((channel.get("snippet") or {}).get("title"))
        uploads_id = _single_line(
            (((channel.get("contentDetails") or {}).get("relatedPlaylists") or {}).get("uploads"))
        )
        if not channel_id or not channel_title or not uploads_id:
            raise YouTubeToolError("The channel does not expose a usable uploads playlist.")
        return channel_id, channel_title, uploads_id

    def _list_public_uploads(
        self,
        session: requests.Session,
        uploads_playlist_id: str,
        requested_count: int,
    ) -> List[Dict[str, Any]]:
        collected: List[Tuple[int, Dict[str, Any]]] = []
        page_token: Optional[str] = None
        seen_tokens = set()

        while len(collected) < requested_count:
            params: Dict[str, Any] = {
                "part": "snippet,status",
                "playlistId": uploads_playlist_id,
                "maxResults": 50,
                "fields": (
                    "nextPageToken,items(snippet(title,position,resourceId/videoId),status/privacyStatus)"
                ),
            }
            if page_token:
                params["pageToken"] = page_token

            payload = self._get_json(session, "playlistItems", params)
            for item in payload.get("items") or []:
                status = item.get("status") or {}
                snippet = item.get("snippet") or {}
                resource_id = snippet.get("resourceId") or {}
                video_id = _single_line(resource_id.get("videoId"))
                title = _single_line(snippet.get("title"))
                if status.get("privacyStatus") != "public" or not video_id or not title:
                    continue
                try:
                    position = int(snippet.get("position"))
                except (TypeError, ValueError):
                    position = len(collected)
                collected.append(
                    (
                        position,
                        {
                            "video_id": video_id,
                            "title": title,
                            "url": f"https://www.youtube.com/watch?v={video_id}",
                        },
                    )
                )
                if len(collected) >= requested_count:
                    break

            next_token = payload.get("nextPageToken")
            if not next_token:
                break
            next_token = str(next_token)
            if next_token in seen_tokens:
                raise YouTubeToolError("YouTube Data API returned a repeated page token; try again.")
            seen_tokens.add(next_token)
            page_token = next_token

        collected.sort(key=lambda entry: entry[0])
        return [video for _, video in collected[:requested_count]]

    @staticmethod
    def _format_text(
        channel_title: str,
        videos: List[Dict[str, Any]],
        output_format: str,
    ) -> str:
        if output_format == "urls_only":
            return "\n".join(video["url"] for video in videos)
        lines = [f"Channel: {channel_title}"]
        lines.extend(
            f"{index} - {video['title']} - {video['url']}"
            for index, video in enumerate(videos, 1)
        )
        return "\n".join(lines)

    async def list_channel_videos(
        self,
        channel: str,
        count: int = 20,
        output_format: Literal["title_url", "urls_only"] = "title_url",
        __event_emitter__: Optional[Callable[[dict], Awaitable[None]]] = None,
    ) -> str:
        """
        List a YouTube channel's newest public uploads, newest first, using the official uploads playlist.

        Use this when the user supplies a YouTube channel URL, @handle, or UC... channel ID and asks for
        a specific number of recent videos. The default response contains only a short channel header and
        numbered lines in `number - video title - video URL` form. No dates, durations, descriptions,
        commentary, summaries, transcripts, downloads, search results, analytics, or mutations are returned.

        :param channel: YouTube channel ID (UC...), @handle, or a YouTube /channel/UC..., /@handle, or legacy /user/name URL. Legacy /c/name vanity URLs are unsupported; use the @handle or channel ID instead.
        :param count: Exact number of newest public uploads to return when available. Must be 1-500 and no greater than the max_video_count Valve. Defaults to 20.
        :param output_format: `title_url` (default) for a channel header plus numbered title-and-URL lines, or `urls_only` for one URL per line.
        :return: Concise newest-first video list with no dates or extra metadata, or an actionable error.
        """

        async def emit(message: str, done: bool) -> None:
            if __event_emitter__:
                await __event_emitter__(
                    {"type": "status", "data": {"description": message, "done": done}}
                )

        try:
            count = int(count)
        except (TypeError, ValueError):
            return "Error: count must be an integer from 1 to 500."
        cap = max(1, min(int(self.valves.max_video_count), MAX_VIDEO_COUNT))
        if count < 1 or count > cap:
            return f"Error: count must be between 1 and {cap}."
        if output_format not in {"title_url", "urls_only"}:
            return "Error: output_format must be title_url or urls_only."

        try:
            filter_name, filter_value = parse_channel_reference(channel)
        except ValueError as exc:
            return f"Error: {exc}"

        if not (self.valves.youtube_data_api_key or "").strip():
            return (
                "Error: YouTube Channel Videos is installed but not configured. Open Workspace > Tools > "
                "YouTube Channel Videos > Valves, then paste the key into the masked "
                "youtube_data_api_key field."
            )

        await emit("Reading the channel uploads playlist...", False)

        def run() -> str:
            with requests.Session() as session:
                _, channel_title, uploads_id = self._resolve_channel(
                    session, filter_name, filter_value
                )
                videos = self._list_public_uploads(session, uploads_id, count)
                return self._format_text(channel_title, videos, output_format)

        try:
            result = await asyncio.to_thread(run)
        except YouTubeToolError as exc:
            await emit("YouTube listing failed.", True)
            return f"Error: {exc}"

        await emit("YouTube video list ready.", True)
        return result
